import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/lib/analytics'

export default async function Home() {
  // Request APIs like headers() cannot be called inside `after` in a Server
  // Component — read the values during render and close over them instead.
  const userAgent = (await headers()).get('user-agent') ?? 'unknown'

  after(() => {
    logPageView({ path: '/', userAgent, timestamp: Date.now() })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>We&apos;re glad you&apos;re here.</p>
    </main>
  )
}

